Istio Service Mesh & API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Istio Service Mesh & API Gateway container

Container_Boundary(istio_container, "Istio Service Mesh & API Gateway") {
    Component(EnvoyIngressProxy, "Envoy Ingress Proxy", "Envoy proxy", "Handles edge routing, TLS termination, geo-restrictions, and mTLS enforcement.")
    Component(ExtAuthzAuthorizationFilter, "Ext_Authz Authorization Filter", "Istio Extension", "Interfacing with the Consent Manager for request authorization.")
    Component(TrafficManagementRouter, "Traffic Management Router", "Istio Service Mesh", "Manages multi-region traffic routing and rate limiting.")
}

Rel(EnvoyIngressProxy, ExtAuthzAuthorizationFilter, "Delegates request authorization", "gRPC over mTLS")
Rel(EnvoyIngressProxy, TrafficManagementRouter, "Routes traffic to regional BFFs and services", "gRPC over mTLS")

@enduml

Mediasoup SFU.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(mediasoup_sfu, "Mediasoup SFU") {
    Component(Worker_Pool, "Worker Pool", "C++ / Node.js", "Manages underlying media workers, controls transport and producer/consumer creation.")
    Component(Room_and_Signaling_Manager, "Room & Signaling Manager", "Node.js", "Handles signaling and coordinates transport and producer/consumer creation.")
    Component(Simulcast_and_Adaptation_Controller, "Simulcast & Adaptation Controller", "C++", "Controls low-bandwidth adaptation and feeds bitrate and packet loss metrics.")
    Component(Telemetry_and_Stats_Exporter, "Telemetry & Stats Exporter", "Node.js / Prometheus", "Exports QoE telemetry, connection state changes, and performance stats.")
}

Rel(Room_and_Signaling_Manager, Worker_Pool, "Controls transport and producer/consumer creation", "IPC")
Rel(Simulcast_and_Adaptation_Controller, Telemetry_and_Stats_Exporter, "Feeds bitrate and packet loss metrics", "Internal IPC")

@enduml
